// === PARSER DE CLASIFICACIÓN IA v3 ===
// Compatible con OpenAI Responses API

const input = $input.first().json;

// Navegar la estructura de Responses API
// Ruta: output[] → content[] → buscar type "output_text" → text
let responseText = '';

if (input.output) {
  // Responses API format
  for (const block of input.output) {
    if (block.content) {
      for (const content of block.content) {
        if (content.type === 'output_text' && content.text) {
          responseText = content.text;
          break;
        }
      }
    }
    if (responseText) break;
  }
} else if (input.message?.content) {
  responseText = input.message.content;
} else if (input.text) {
  responseText = input.text;
}

// Limpiar posibles backticks
responseText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let classification;
try {
  classification = JSON.parse(responseText);
} catch (e) {
  classification = {
    intent: 'other',
    sentiment: 'neutral',
    urgency: 'low',
    language: 'es',
    summary: 'No se pudo clasificar',
    has_invoice: false
  };
}

// Recuperar datos normalizados del nodo Normalizar Mensaje
const normalized = $('Normalizar Mensaje').first().json;

return {
  json: {
    ...normalized,
    classification: classification,
    intent: classification.intent,
    sentiment: classification.sentiment,
    urgency: classification.urgency,
    language: classification.language,
    summary: classification.summary,
    route_to: classification.has_invoice || normalized.has_attachment ? 'ocr' : classification.intent
  }
};

// === NORMALIZADOR UNIFICADO EcomBot360 ===
// Estandariza mensajes de cualquier canal al formato interno

const telegramData = $input.first().json;
const message = telegramData.message || telegramData.channel_post || {};

// Detectar si hay archivo adjunto (foto, documento)
let attachments = [];
let messageText = message.text || message.caption || '';

if (message.photo) {
  // Telegram envía array de resoluciones, tomamos la más alta
  const bestPhoto = message.photo[message.photo.length - 1];
  attachments.push({
    type: 'photo',
    file_id: bestPhoto.file_id,
    mime_type: 'image/jpeg'
  });
}

if (message.document) {
  attachments.push({
    type: 'document',
    file_id: message.document.file_id,
    file_name: message.document.file_name || 'document',
    mime_type: message.document.mime_type || 'application/octet-stream'
  });
}

// Construir objeto normalizado
const normalized = {
  channel: 'telegram',
  sender_id: String(message.from?.id || message.chat?.id || 'unknown'),
  sender_name: [message.from?.first_name, message.from?.last_name].filter(Boolean).join(' ') || 'Desconocido',
  message_text: messageText,
  timestamp: new Date(message.date * 1000).toISOString(),
  has_attachment: attachments.length > 0,
  attachments: attachments,
  raw_channel_data: {
    chat_id: message.chat?.id,
    message_id: message.message_id
  }
};

return { json: normalized };
